"""MPS projection + activation ops.

Thin PyTorch wrappers that mirror the CUDA cublasLt / cubin entry points:

- ``linear_mps`` — ``F.linear``, keeping the CUDA signature (``out=`` reuse,
  optional 3D batch reshape).
- ``gelu_cute_mps`` — ``F.gelu`` with the CUDA shape validation stripped
  (no per-variant cubin on MPS, any last-dim works).
"""

import torch
import torch.nn.functional as F

from kestrel_kernels.mps import _native


_DENSE_GEMV_MAX_TOKENS = 1
# Swept locally on ayanami (Apple M2): this direct GEMV path wins for MD2
# decode expansion/square projections, but not for K>N fc2 or vocab-sized
# lm_head. Keep the gate narrow until we sweep more Apple GPU tiers.
_DENSE_GEMV_MAX_OUTPUT_DIM = 8192


def _linear_gemv_available() -> bool:
    return _native.ops is not None and hasattr(_native.ops, "linear_gemv_bias_into")


def _linear_gemv_eligible(
    x: torch.Tensor,
    w: torch.Tensor,
    bias: torch.Tensor | None,
    out: torch.Tensor | None,
) -> bool:
    if bias is None or not _linear_gemv_available():
        return False
    if x.device.type != "mps" or x.dtype != torch.float16:
        return False
    if w.device != x.device or bias.device != x.device:
        return False
    if w.dtype != x.dtype or bias.dtype != x.dtype:
        return False
    if x.ndim != 2 or w.ndim != 2 or bias.ndim != 1:
        return False
    if x.size(0) > _DENSE_GEMV_MAX_TOKENS:
        return False
    if x.size(1) != w.size(1) or bias.size(0) != w.size(0):
        return False
    if w.size(0) > _DENSE_GEMV_MAX_OUTPUT_DIM or x.size(1) > w.size(0):
        return False
    if not (x.is_contiguous() and w.is_contiguous() and bias.is_contiguous()):
        return False
    if out is not None:
        if out.device != x.device or out.dtype != x.dtype:
            return False
        if out.numel() != x.size(0) * w.size(0) or not out.is_contiguous():
            return False
    return True


def linear_mps(
    x: torch.Tensor,
    w: torch.Tensor,
    bias: torch.Tensor | None = None,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Linear projection ``out = x @ w.T [+ bias]`` on MPS.

    Matches ``kestrel_kernels.linear_ops.linear`` exactly: when ``x`` is
    3D ``(bsz, t, c)`` the call is flattened to 2D, written into (or
    allocated as) a 2D ``out`` buffer, and the returned tensor is a 3D
    view ``(bsz, t, out_dim)``.
    """
    if x.ndim == 3:
        bsz, t, c = x.shape
        x2 = x.reshape(bsz * t, c)
    else:
        bsz = 0
        x2 = x
    if _linear_gemv_eligible(x2, w, bias, out):
        if out is None:
            out2 = torch.empty((x2.size(0), w.size(0)), device=x2.device, dtype=x2.dtype)
            out = out2
        else:
            out2 = out.view(x2.size(0), w.size(0))
        _native.ops.linear_gemv_bias_into(out2, x2, w, bias)
        if bsz:
            return out.view(bsz, t, w.size(0))
        return out
    result = F.linear(x2, w, bias)
    if out is not None:
        out.copy_(result)
    else:
        out = result
    if bsz:
        return out.view(bsz, t, w.size(0))
    return out


def gelu_cute_mps(
    inp: torch.Tensor,
    out: torch.Tensor | None = None,
    *,
    add: torch.Tensor | None = None,
    require_native: bool = False,
    require_packed: bool = False,
    approximate: str = "none",
) -> torch.Tensor:
    """Plain GELU activation on MPS.

    Matches ``kestrel_kernels.gelu_residual.gelu_cute`` — including the
    contract that the returned tensor has ``inp``'s logical shape even
    when the caller hands us a flattened scratch ``out`` buffer (see
    ``gelu_residual/dispatch.py::_normalize_gelu_out``).
    """
    if approximate not in ("none", "tanh"):
        raise ValueError(f"unsupported GELU approximation: {approximate}")
    if add is not None and approximate != "none":
        raise ValueError("GELU add epilogues currently require approximate='none'")
    if require_native or require_packed:
        raise RuntimeError(
            "kestrel-kernels MPS backend has no packed/native GELU artifact"
        )
    if inp.dtype != torch.bfloat16:
        raise ValueError(f"gelu_cute requires bfloat16, got {inp.dtype}")
    if inp.ndim == 0:
        raise ValueError("gelu_cute input must have at least one dimension")

    result = F.gelu(inp, approximate=approximate)
    if add is not None:
        dim = int(inp.shape[-1])
        if add.ndim != 2 or int(add.shape[1]) != dim:
            raise ValueError(
                "gelu_cute add tensor must have shape [repeat_rows, dim], got "
                f"{tuple(add.shape)} for dim={dim}"
            )
        if int(add.shape[0]) <= 0:
            raise ValueError("gelu_cute add repeat_rows must be positive")
        if add.dtype != inp.dtype or add.device != inp.device:
            raise ValueError("gelu_cute add tensor must match input device and dtype")
        if not add.is_contiguous():
            raise ValueError("gelu_cute add tensor must be contiguous")
        rows = result.reshape(-1, dim)
        repeats = (int(rows.shape[0]) + int(add.shape[0]) - 1) // int(add.shape[0])
        rows.add_(add.repeat((repeats, 1))[: int(rows.shape[0])])

    if out is None:
        return result
    out.copy_(result.reshape(out.shape))
    if out.shape != inp.shape:
        if out.numel() != inp.numel():
            raise ValueError(
                "gelu_cute_mps out tensor must match the input shape or "
                f"have the same number of elements, got "
                f"inp={tuple(inp.shape)} out={tuple(out.shape)}"
            )
        return out.view_as(inp)
    return out


def fused_linear_bias_residual_into_mps(
    *,
    x: torch.Tensor,
    w: torch.Tensor,
    b: torch.Tensor,
    residual: torch.Tensor,
    out: torch.Tensor,
) -> None:
    """In-place ``out = residual + F.linear(x, w, b)`` on MPS.

    Mirrors ``kestrel_kernels.fused_linear_residual_ops.fused_linear_bias_residual_into``.
    The CUDA kernel fuses the GEMM with the residual add in one launch; on
    MPS we do the equivalent in two torch ops.
    """
    if _linear_gemv_eligible(x.reshape(-1, x.shape[-1]), w, b, out):
        x2 = x.reshape(-1, x.shape[-1])
        out2 = out.view(x2.size(0), w.size(0))
        residual2 = residual.reshape(x2.size(0), w.size(0))
        if residual2.is_contiguous():
            _native.ops.linear_gemv_bias_residual_into(out2, x2, w, b, residual2)
            return
    result = residual + F.linear(x, w, b)
    out.copy_(result.reshape(out.shape))


__all__ = [
    "linear_mps",
    "gelu_cute_mps",
    "fused_linear_bias_residual_into_mps",
]
